  "implementation": "def solve(case):
    # Extract required fields from payload
    initial = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']

    # Validate that initial state exists
    if initial not in transitions:
        raise ValueError(f"Initial state '{initial}' not found in transitions")

    # Validate every state in the transition map
    for state_name, state_data in transitions.items():
        kind = state_data.get('kind')
        if kind not in ('action', 'final'):
            raise ValueError(f"State '{state_name}' has invalid kind '{kind}'")
        if kind == 'action':
            action = state_data.get('action')
            if not isinstance(action, str):
                raise ValueError(f"State '{state_name}' action missing or invalid")
            if action not in tool_obs:
                raise ValueError(f"State '{state_name}' action '{action}' not in tool_observations")
            next_by_obs = state_data.get('next_by_observation', {})
            default_next = state_data.get('default_next')
            for obs, target in next_by_obs.items():
                if target not in transitions:
                    raise ValueError(f"State '{state_name}' next_by_observation target '{target}' not in transitions")
            if default_next is not None and default_next not in transitions:
                raise ValueError(f"State '{state_name}' default_next '{default_next}' not in transitions")
        elif kind == 'final':
            value = state_data.get('value')
            if not isinstance(value, str):
                raise ValueError(f"Final state '{state_name}' missing or invalid value")

    current_state = initial
    steps = 0
    trace = []
    final_value = None
    status = None

    # Handle case where the initial state is already final
    state_info = transitions[current_state]
    if state_info['kind'] == 'final':
        final_value = state_info['value']
        status = 'completed'
        return {'final': final_value, 'status': status, 'trace': trace}

    # Bounded ReAct loop
    while steps < max_steps:
        state_info = transitions[current_state]
        if state_info['kind'] == 'final':
            # Should not happen because we check after transition, but safe guard
            break

        action = state_info['action']
        observation = tool_obs[action]  # deterministic observation from fixture
        next_by_obs = state_info.get('next_by_observation', {})
        default_next = state_info.get('default_next')

        if observation in next_by_obs:
            next_state = next_by_obs[observation]
        else:
            next_state = default_next

        if next_state is None:
            raise ValueError(f"No next state for observation '{observation}' and no default_next in state '{current_state}'")

        steps += 1
        trace.append({
            'step': steps,
            'action': action,
            'observation': observation,
            'state': next_state
        })

        current_state = next_state
        next_state_info = transitions[current_state]
        if next_state_info['kind'] == 'final':
            final_value = next_state_info['value']
            status = 'completed'
            break
    else:
        # Exhausted max_steps without reaching a final state
        status = 'max_steps_exceeded'
        final_value = None

    return {'final': final_value, 'status': status, 'trace': trace}"
